public class DialogueController : MonoBehaviour
{
    [SerializeField] private TextAsset inkJSONAsset;
    private Story _story;
    private UIDocument _uiDocument;
    private Label _dialogueLabel;
    private VisualElement _choicesContainer;

    void Start()
    {
        _story = new Story(inkJSONAsset.text);
        _uiDocument = GetComponent<UIDocument>();
        SetupUI();
        ContinueStory();
    }

    void SetupUI()
    {
        var root = _uiDocument.rootVisualElement;
        _dialogueLabel = root.Q<Label>("dialogue-text");
        _choicesContainer = root.Q<VisualElement>("choices-container");
    }

    void ContinueStory()
    {
        if (_story.canContinue)
        {
            string text = _story.Continue();
            _dialogueLabel.text = text;
            DisplayChoices();
        }
        else
        {
            EndDialogue();
        }
    }

    void DisplayChoices()
    {
        _choicesContainer.Clear();

        foreach (var choice in _story.currentChoices)
        {
            var button = new Button(() => MakeChoice(choice.index))
            {
                text = choice.text
            };
            button.AddToClassList("choice-button");
            _choicesContainer.Add(button);
        }
    }

    void MakeChoice(int choiceIndex)
    {
        _story.ChooseChoiceIndex(choiceIndex);
        ContinueStory();
    }
}

public class PlayerController : MonoBehaviour
{
    [Header("Movement")]
    [SerializeField] private float moveSpeed = 5f;
    [SerializeField] private float sprintMultiplier = 1.5f;

    [Header("Components")]
    [SerializeField] private Animator animator;
    [SerializeField] private SpriteRenderer spriteRenderer;

    private NavMeshAgent _agent;
    private Vector2 _input;
    private bool _isSprinting;

    private static readonly int AnimSpeed = Animator.StringToHash("Speed");
    private static readonly int AnimHorizontal = Animator.StringToHash("Horizontal");
    private static readonly int AnimVertical = Animator.StringToHash("Vertical");

    void Awake()
    {
        _agent = GetComponent<NavMeshAgent>();
        _agent.updateRotation = false;
        _agent.updateUpAxis = false;
    }

    void Update()
    {
        HandleInput();
        UpdateAnimation();
    }

    void FixedUpdate()
    {
        Move();
    }

    void HandleInput()
    {
        _input.x = Input.GetAxisRaw("Horizontal");
        _input.y = Input.GetAxisRaw("Vertical");
        _isSprinting = Input.GetKey(KeyCode.LeftShift);
    }

    void Move()
    {
        float currentSpeed = _isSprinting ? 
            moveSpeed * sprintMultiplier : moveSpeed;

        Vector3 movement = new Vector3(_input.x, _input.y, 0).normalized;
        _agent.velocity = movement * currentSpeed;
    }

    void UpdateAnimation()
    {
        animator.SetFloat(AnimHorizontal, _input.x);
        animator.SetFloat(AnimVertical, _input.y);
        animator.SetFloat(AnimSpeed, _input.sqrMagnitude);

        if (_input.x != 0)
        {
            spriteRenderer.flipX = _input.x < 0;
        }
    }
}

