public class InputManager : MonoBehaviour
{
    private PlayerInput _playerInput;
    private InputAction _moveAction;
    private InputAction _interactAction;
    private InputAction _sprintAction;

    void Awake()
    {
        _playerInput = GetComponent<PlayerInput>();
        _moveAction = _playerInput.actions["Move"];
        _interactAction = _playerInput.actions["Interact"];
        _sprintAction = _playerInput.actions["Sprint"];

        _interactAction.performed += OnInteract;
    }

    void OnDestroy()
    {
        _interactAction.performed -= OnInteract;
    }

    public Vector2 GetMoveInput()
    {
        return _moveAction.ReadValue<Vector2>();
    }

    public bool IsSprinting()
    {
        return _sprintAction.IsPressed();
    }

    void OnInteract(InputAction.CallbackContext context)
    {
        InteractionSystem.Instance.TryInteract();
    }
}

public class CharacterAnimator : MonoBehaviour
{
    private Animator _animator;
    private static readonly int MoveX = Animator.StringToHash("MoveX");
    private static readonly int MoveY = Animator.StringToHash("MoveY");
    private static readonly int Speed = Animator.StringToHash("Speed");
    private static readonly int IsInteracting = Animator.StringToHash("IsInteracting");

    void Awake()
    {
        _animator = GetComponent<Animator>();
    }

    public void SetMovement(Vector2 movement)
    {
        _animator.SetFloat(MoveX, movement.x);
        _animator.SetFloat(MoveY, movement.y);
        _animator.SetFloat(Speed, movement.magnitude);
    }

    public void TriggerInteraction(string interactionName)
    {
        _animator.SetTrigger(IsInteracting);
        _animator.SetLayerWeight(1, 1f);
    }

    public void OnInteractionComplete()
    {
        _animator.SetLayerWeight(1, 0f);
    }
}

