[CreateAssetMenu(fileName = "New Quest", menuName = "Game/Quest")]
public class Quest : ScriptableObject
{
    public string questId;
    public string questName;
    public string description;
    public QuestObjective[] objectives;
    public Quest[] prerequisites;
    public Reward[] rewards;
}

public class QuestManager : MonoBehaviour
{
    private Dictionary<string, QuestState> _activeQuests = 
        new Dictionary<string, QuestState>();

    public void StartQuest(Quest quest)
    {
        if (!CanStartQuest(quest)) return;

        var state = new QuestState
        {
            quest = quest,
            status = QuestStatus.Active,
            completedObjectives = new HashSet<int>()
        };

        _activeQuests[quest.questId] = state;
        GameEvents.OnQuestStarted?.Invoke(quest);
    }

    public void UpdateObjective(string questId, int objectiveIndex)
    {
        if (!_activeQuests.TryGetValue(questId, out var state))
            return;

        state.completedObjectives.Add(objectiveIndex);

        if (state.completedObjectives.Count == state.quest.objectives.Length)
        {
            CompleteQuest(questId);
        }
    }

    private void CompleteQuest(string questId)
    {
        var state = _activeQuests[questId];
        state.status = QuestStatus.Completed;
        GrantRewards(state.quest.rewards);
        GameEvents.OnQuestCompleted?.Invoke(state.quest);
    }

    private bool CanStartQuest(Quest quest)
    {
        foreach (var prereq in quest.prerequisites)
        {
            if (!_activeQuests.ContainsKey(prereq.questId) ||
                _activeQuests[prereq.questId].status != QuestStatus.Completed)
            {
                return false;
            }
        }
        return true;
    }
}

public class AINavigationController : MonoBehaviour
{
    [SerializeField] private float wanderRadius = 10f;
    [SerializeField] private float wanderTimer = 5f;

    private NavMeshAgent _agent;
    private float _timer;

    void Awake()
    {
        _agent = GetComponent<NavMeshAgent>();
        _agent.updateRotation = false;
        _agent.updateUpAxis = false;
    }

    void Update()
    {
        _timer += Time.deltaTime;

        if (_timer >= wanderTimer)
        {
            Vector3 newPos = RandomNavSphere(transform.position, wanderRadius);
            _agent.SetDestination(newPos);
            _timer = 0;
        }
    }

    public void MoveTo(Vector3 destination)
    {
        _agent.SetDestination(destination);
    }

    public void Stop()
    {
        _agent.isStopped = true;
    }

    Vector3 RandomNavSphere(Vector3 origin, float distance)
    {
        Vector3 randomDirection = Random.insideUnitSphere * distance;
        randomDirection += origin;

        NavMeshHit navHit;
        NavMesh.SamplePosition(randomDirection, out navHit, distance, -1);

        return navHit.position;
    }
}

