public class GameSaveData
{
    public Vector3 playerPosition;
    public List<string> completedQuests;
    public Dictionary<string, int> inventory;
    public Dictionary<string, bool> worldState;
    public float playTime;
}

public class SaveLoadSystem : MonoBehaviour
{
    private const string SaveKey = "GameSave_";

    public void SaveGame(int slotIndex)
    {
        var saveData = new GameSaveData
        {
            playerPosition = PlayerController.Instance.transform.position,
            completedQuests = QuestManager.Instance.GetCompletedQuestIds(),
            inventory = InventoryManager.Instance.GetInventoryData(),
            worldState = WorldStateManager.Instance.GetStateData(),
            playTime = Time.time
        };

        string json = JsonUtility.ToJson(saveData, true);
        PlayerPrefs.SetString(SaveKey + slotIndex, json);
        PlayerPrefs.Save();
    }

    public GameSaveData LoadGame(int slotIndex)
    {
        string key = SaveKey + slotIndex;
        if (!PlayerPrefs.HasKey(key))
            return null;

        string json = PlayerPrefs.GetString(key);
        return JsonUtility.FromJson<GameSaveData>(json);
    }

    public void ApplySaveData(GameSaveData data)
    {
        PlayerController.Instance.transform.position = data.playerPosition;
        QuestManager.Instance.LoadCompletedQuests(data.completedQuests);
        InventoryManager.Instance.LoadInventory(data.inventory);
        WorldStateManager.Instance.LoadState(data.worldState);
    }
}

